using System.Collections.Generic;
using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "AfflictionDefaultEffectAction", menuName = "Data/Battle/Battle Actions/Enchantment Actions/AfflictionDefaultEffect Action")]
public class AfflictionDefaultEffectAction : DefaultEffectAction
{
	public override void AreaCastTargetAmount(List<GameObject> targets, int amount, GameObject source)
	{
		base.AreaCastTargetAmount(targets, amount, source);
		ActivateOnCorruptAfflictionSingleTimeOmens(null, amount, source);
	}

	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		base.CastTargetAmount(target, amount, source);
		ActivateOnCorruptAfflictionSingleTimeOmens(target, amount, source);
	}

	private void ActivateOnCorruptAfflictionSingleTimeOmens(GameObject target, int amount, GameObject source)
	{
		BattleHandler instance = ReferenceSingleton<BattleHandler>.Instance;
		if (instance.IsSourcePlayer(source) || instance.IsSourceCompanions(source))
		{
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateOnCorruptAfflictionSingleTimeOmens(amount);
		}
	}

	public override void DefaultCast(GameObject target, int amount, GameObject source, bool effectFeedback, bool gainingEffectVFXAndSFX)
	{
		BattleHandler instance = ReferenceSingleton<BattleHandler>.Instance;
		if (instance.IsSourcePlayer(source) || ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source))
		{
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateOnCorruptAfflictionMultipleTimesOmens(target, amount);
		}
		if (!instance.IsSourceEnemy(source) && source != null && instance.IsTargetEnemy(target))
		{
			if (ReferenceSingleton<SothisOmensHandler>.Instance.IsBehenianHourglassActive())
			{
				ReferenceSingleton<MiscOmensHandler>.Instance.ActivateOnCorruptEnemyOmens(target, amount);
			}
			ReferenceSingleton<SothisOmensHandler>.Instance.ActivateOnCorruptAfflictionEnemyMultipleTimesOmens(amount);
		}
		base.DefaultCast(target, amount, source, effectFeedback, gainingEffectVFXAndSFX);
	}
}
